+++ b/training/level-1/L1-016-unit-converter/convertUnit.mjs
@@ -0,0 +1,66 @@
+export function convertUnit(value, from, to) {
+  const isFinite = (n) => Number.isFinite(n);
+  const normalize = (n) => n === 0 ? 0 : n;
+
+  if (!isFinite(value)) {
+    throw new TypeError('value must be a finite number');
+  }
+
+  const units = ['mm', 'cm', 'm', 'km', 'ft', 'yd', 'mi'];
+  const massUnits = ['mg', 'g', 'kg', 'oz', 'lb'];
+  const tempUnits = ['C', 'F', 'K'];
+
+  if (!units.includes(from) && !massUnits.includes(from) && !tempUnits.includes(from)) {
+    throw new RangeError('Invalid unit: ' + from);
+  }
+  if (!units.includes(to) && !massUnits.includes(to) && !tempUnits.includes(to)) {
+    throw new RangeError('Invalid unit: ' + to);
+  }
+
+  const isLength = units.includes(from);
+  const isMass = massUnits.includes(from);
+  const isTemp = tempUnits.includes(from);
+
+  if (isLength || isMass) {
+    let siValue;
+    if (isLength) {
+      const factors = { mm: 0.001, cm: 0.01, m: 1, km: 1000, ft: 0.3048, yd: 0.9144, mi: 1609.344 };
+      siValue = value * factors[from];
+    } else {
+      const factors = { mg: 1e-6, g: 1e-3, kg: 1, oz: 0.028349523125, lb: 0.45359237 };
+      siValue = value * factors[from];
+    }
+
+    let result;
+    if (isLength) {
+      const toFactor = factors[to];
+      result = siValue / toFactor;
+    } else {
+      const toFactor = factors[to];
+      result = siValue / toFactor;
+    }
+
+    return normalize(result);
+  } else {
+    // Temperature conversion
+    let celsius;
+    if (from === 'C') {
+      celsius = value;
+    } else if (from === 'F') {
+      celsius = (value - 32) * 5 / 9;
+    } else if (from === 'K') {
+      celsius = value - 273.15;
+    }
+
+    let result;
+    if (to === 'C') {
+      result = celsius;
+    } else if (to === 'F') {
+      result = celsius * 9 / 5 + 32;
+    } else if (to === 'K') {
+      result = celsius + 273.15;
+    }
+
+    return normalize(result);
+  }
+}

